<script lang="ts">const steps=['Submitted','Under Review','Requirement Discussion','Counselling','Application','Admission'];</script><div class="max-w-3xl space-y-6"><div><h1 class="text-3xl font-bold text-white">Enquiry Status</h1><p class="text-text-secondary mt-2">Follow each step of your admission enquiry.</p></div><div class="bg-card border border-white/10 rounded-2xl p-6 grid sm:grid-cols-2 gap-5"><div><p class="meta">Enquiry ID</p><p class="text-white">DI-24018</p></div><div><p class="meta">Course / Program</p><p class="text-white">MCA</p></div><div><p class="meta">Submitted Date</p><p class="text-white">12 September 2026</p></div><div><p class="meta">Current Status</p><p class="text-accent">Application Started</p></div></div><div class="bg-card border border-white/10 rounded-2xl p-6"><h2 class="text-white font-bold">Admission Timeline</h2><div class="mt-6 space-y-5">{#each steps as step,i}<div class="flex gap-4"><span class:complete={i<4} class:current={i===4} class="timeline-dot">{i<4?'✓':i+1}</span><div><p class="text-white font-medium">{step}</p><p class="text-sm text-text-secondary mt-1">{i===4?'Complete your application information to continue.':i<4?'Completed':'Available after your application is reviewed.'}</p></div></div>{/each}</div></div><div class="bg-card border border-white/10 rounded-2xl p-6"><p class="meta">Admission team update</p><p class="text-text-secondary mt-2">Please complete the remaining application details before your next counselling discussion.</p><p class="text-sm text-accent mt-4">Next step: Complete application details</p></div></div><style>.meta{font-size:.7rem;text-transform:uppercase;letter-spacing:.12em;color:#a7a4b4;margin-bottom:.3rem}.timeline-dot{width:2rem;height:2rem;flex:none;border-radius:999px;display:grid;place-items:center;background:rgba(255,255,255,.08);color:#a7a4b4}.timeline-dot.complete{background:rgba(164,123,224,.35);color:white}.timeline-dot.current{border:1px solid #a47be0;color:#a47be0}</style>
